mapper.select:
SELECT target, code_hash, expires_at, consumed_at, attempt_count, created_at
  FROM MEMBER_PASSWORD_RESETS
 WHERE target = #{target}

mapper.update:
UPDATE MEMBER_PASSWORD_RESETS
   SET consumed_at = #{now}
 WHERE target = #{target}
   AND code_hash = #{codeHash}
   AND expires_at > #{now}
   AND consumed_at IS NULL
   AND attempt_count < #{maxAttempts}

UPDATE MEMBER_PASSWORD_RESETS
   SET attempt_count = attempt_count + 1
 WHERE target = #{target}
   AND consumed_at IS NULL
   AND expires_at > #{now}
   AND attempt_count < #{maxAttempts}
